@import 'tailwindcss';
@config "../../../tailwind.config.mjs";
@import 'katex/dist/katex.min.css';

@layer base {
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    font-size: unset;
    font-weight: unset;
  }

  :root,
  [data-theme='light'] {
    /* Light background - warm cream paper */
    --background: 40 25% 97%; /* #fcfaf6 - warm cream, feels premium */
    --foreground: 220 9% 11%; /* #1a1c1e */

    /* Card: pure white for elevated surfaces */
    --card: 0 0% 99%; /* #fdfdfd — nearly white, very slight contrast from true white */
    --card-foreground: 220 9% 11%;

    --popover: 0 0% 100%;
    --popover-foreground: 220 9% 11%;

    /* Primary: warm burgundy red (brand color) */
    --primary: 353 73% 29%; /* #91262C */
    --primary-soft: 0 45% 98%; /* #fdf2f2 - light wash for hover states */
    --primary-foreground: 0 0% 100%;

    /* Secondary: muted sage green (accent) */
    --secondary: 113 12% 41%; /* #5D725B */
    --secondary-foreground: 0 0% 100%;

    /* Muted: light backgrounds and secondary text */
    --muted: 210 14% 95%; /* #f8f9fa */
    --muted-foreground: 220 8% 45%; /* #6c7278 */

    /* Accent: vivid purple (keeping for backward compatibility) */
    --accent: 271 91% 65%;
    --accent-foreground: 0 0% 100%;

    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 0 0% 100%;

    /* Border: warm stone — premium stationery feel */
    --border: 30, 8%, 82%; /* hsl(30,8%,82%) — warm light gray, not blue */

    --input: 210 14% 97%; /* #f8f9fa */

    /* Focus ring follows primary */
    --ring: 353 73% 29%;

    /* Radius system */
    --radius: 0.75rem; /* 12px - default */

    /* Shadow system - for card elevation on light backgrounds */
    --shadow-card: 0 4px 16px 0 rgb(0 0 0 / 0.1), 0 2px 6px -1px rgb(0 0 0 / 0.07);
    --shadow-card-hover: 0 8px 24px 0 rgb(0 0 0 / 0.15), 0 4px 8px -1px rgb(0 0 0 / 0.08);
    --shadow-modal: 0 10px 25px -5px rgb(0 0 0 / 0.15), 0 4px 10px -2px rgb(0 0 0 / 0.1);

    --success: 142 71% 45%;
    --warning: 38 92% 50%;
    --error: 0 72% 51%;

    /* Badge colors - for course categories */
    --badge-orange: 25 95% 53%; /* Orange badge */
    --badge-orange-bg: 24 95% 97%; /* Light orange background */

    /* Semantic colors - components use these */
    --header-bg: var(--card);
    --header-fg: var(--card-foreground);
    --footer-bg: var(--card);

    /* Interactive element states */
    --hover-bg: var(--muted);
    --selected-bg: var(--muted);
    --selected-fg: var(--foreground);

    /* Form elements - slightly altered background for visual distinction */
    --form-bg: var(--input);
    --form-border: var(--border);
    --form-placeholder: var(--muted-foreground);

    /* Command palette / Modals */
    --surface-elevated: var(--background);
    --surface-elevated-fg: var(--foreground);

    /* Text highlight tokens - for markdown ::text-highlight-N{} syntax */
    --text-highlight-1: 0 72% 51%; /* Red */
    --text-highlight-2: 25 95% 53%; /* Orange */
    --text-highlight-3: 45 93% 47%; /* Yellow */
    --text-highlight-4: 142 71% 45%; /* Green */
    --text-highlight-5: 217 91% 60%; /* Blue */
    --text-highlight-6: 271 91% 65%; /* Purple */
    --text-highlight-7: 330 81% 60%; /* Pink */
    --text-highlight-8: 220 8% 45%; /* Gray */

    /* Course tab accent colors — also used for exercise question type accents */
    --tab-learn: 217 91% 60%; /* Blue — MCQ */
    --tab-practice: 0 72% 51%; /* Red — True/False */
    --tab-exams: 330 81% 60%; /* Pink — Matching */
    --tab-ask: 142 71% 45%; /* Green — Free Response */
  }

  [data-theme='dark'] {
    /* Background: deep charcoal with warm undertone — NOT blue */
    --background: 30 8% 7%;
    --foreground: 30 10% 94%;

    /* Card: warm dark gray — clearly distinct from background */
    --card: 30 6% 10%;
    --card-foreground: 30 10% 94%;

    --popover: 30 6% 10%;
    --popover-foreground: 30 10% 94%;

    /* Primary: vibrant coral-red */
    --primary: 353 73% 56%;
    --primary-soft: 353 73% 15%;
    --primary-foreground: 0 0% 100%;

    /* Secondary: medium warm gray */
    --secondary: 30 8% 16%;
    --secondary-foreground: 30 10% 85%;

    /* Muted: lighter warm surface for contrast */
    --muted: 30 6% 18%;
    --muted-foreground: 30 6% 55%;

    /* Accent: vibrant purple — cool contrast to warm bg */
    --accent: 261 75% 65%;
    --accent-foreground: 0 0% 100%;

    --destructive: 0 70% 35%;
    --destructive-foreground: 0 0% 95%;

    /* Borders: warm gray — visible, same family as bg/card */
    --border: 30, 8%, 24%;
    --input: 30 6% 15%;

    /* Focus ring follows primary */
    --ring: 353 73% 56%;

    /* Shadow system - darker shadows for dark mode */
    --shadow-card: 0 4px 16px 0 rgb(0 0 0 / 0.3);
    --shadow-card-hover: 0 8px 24px 0 rgb(0 0 0 / 0.4);
    --shadow-modal: 0 20px 40px -10px rgb(0 0 0 / 0.5);
    --shadow-dropdown: 0 8px 12px -2px rgb(0 0 0 / 0.3), 0 4px 8px -2px rgb(0 0 0 / 0.2);

    /* Semantic colors - optimized for dark background visibility */
    --success: 158 64% 45%;
    --success-foreground: 0 0% 100%;
    --warning: 38 90% 50%;
    --warning-foreground: 0 0% 10%;
    --error: 0 72% 45%;
    --error-foreground: 0 0% 100%;

    /* Badge colors - for course categories */
    --badge-orange: 25 95% 60%;
    --badge-orange-bg: 25 90% 15%;

    /* Semantic colors - components use these */
    --header-bg: var(--card);
    --header-fg: var(--card-foreground);
    --footer-bg: var(--card);

    /* Interactive element states */
    --hover-bg: 222 25% 16%;
    --selected-bg: 220 25% 20%;
    --selected-fg: 210 40% 95%;

    /* Form elements - slightly altered background for visual distinction */
    --form-bg: var(--card);
    --form-border: var(--border);
    --form-placeholder: var(--muted-foreground);

    /* Command palette / Modals */
    --surface-elevated: var(--card);
    --surface-elevated-fg: var(--card-foreground);

    /* Text highlight tokens - for markdown ::text-highlight-N{} syntax */
    --text-highlight-1: 0 72% 62%; /* Red - brightened */
    --text-highlight-2: 25 95% 62%; /* Orange - brightened */
    --text-highlight-3: 45 93% 60%; /* Yellow - brightened */
    --text-highlight-4: 142 71% 55%; /* Green - brightened */
    --text-highlight-5: 217 91% 68%; /* Blue - brightened */
    --text-highlight-6: 271 91% 72%; /* Purple - brightened */
    --text-highlight-7: 330 81% 68%; /* Pink - brightened */
    --text-highlight-8: 220 10% 65%; /* Gray - brightened for readability */

    /* Course tab accent colors - brightened for dark backgrounds */
    --tab-learn: 217 91% 68%; /* Blue — MCQ */
    --tab-practice: 0 72% 62%; /* Red — True/False */
    --tab-exams: 330 81% 68%; /* Pink — Matching */
    --tab-ask: 142 71% 55%; /* Green — Free Response */
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    background-color: hsl(var(--background));
    color: hsl(var(--foreground));
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    font-family:
      'Assistant',
      -apple-system,
      BlinkMacSystemFont,
      'Segoe UI',
      sans-serif;
    margin: 0;
    overscroll-behavior-y: contain;
    position: relative;
    max-width: 100vw;
    overflow-x: hidden;
  }
}

@layer utilities {
  /* Subtle top radial glow — ambient light effect, visible in both themes */
  [data-theme='light'] {
    background-image: radial-gradient(
      ellipse 80% 60% at 50% -10%,
      hsl(40 20% 95% / 0.6) 0%,
      transparent 70%
    );
  }
  [data-theme='dark'] {
    background-image: radial-gradient(
      ellipse 80% 60% at 50% -10%,
      hsl(30 10% 18% / 0.5) 0%,
      transparent 70%
    );
  }

  /* Decorative accent line under headings */
  .section-accent {
    position: relative;
    display: inline-block;
  }
  .section-accent::after {
    content: '';
    display: block;
    margin-top: 0.5rem;
    width: 3rem;
    height: 3px;
    border-radius: 2px;
    background: linear-gradient(to right, hsl(var(--primary)), hsl(var(--primary) / 0.6));
  }
  .section-accent:is([dir='rtl'])::after {
    background: linear-gradient(to left, hsl(var(--primary)), hsl(var(--primary) / 0.6));
  }

  /* Smooth scrolling for anchor links */
  html {
    scroll-behavior: smooth;
