  }

  /* Hide scrollbar but keep functionality */
  .hide-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
  .hide-scrollbar::-webkit-scrollbar {
    display: none;
  }

  /* Backdrop blur support */
  @supports (backdrop-filter: blur(10px)) {
    .backdrop-blur-lg {
      backdrop-filter: blur(16px);
    }
  }

  /* Smooth transitions for theme changes */
  * {
    transition-property: background-color, border-color, color, fill, stroke;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
    transition-duration: 150ms;
  }

  /* Prevent transition on page load */
  .no-transition {
    transition: none !important;
  }

  /* Gradient utilities inspired by LearnFlow */
  .gradient-border {
    position: relative;
    border-radius: var(--radius);
    background: linear-gradient(to bottom right, hsl(var(--card)), hsl(var(--secondary)));
  }

  .gradient-border::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(135deg, hsl(var(--primary) / 0.4), hsl(var(--accent) / 0.2));
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
  }

  /* Improved gradient for dark mode */
  [data-theme='dark'] .gradient-border::before {
    background: linear-gradient(135deg, hsl(var(--primary) / 0.6), hsl(var(--accent) / 0.4));
  }

  .glass-card {
    background: hsl(var(--card) / 0.6);
    backdrop-filter: blur(12px);
    border: 1px solid hsl(var(--border));
  }
}

html {
  opacity: 0;
  /* Background on html prevents white flash on mobile scroll bounce / pull-to-refresh */
  background-color: hsl(var(--background));
}

html[data-theme='dark'],
html[data-theme='light'] {
  opacity: initial;
}

/* Rich Text Content Styles */
.rich-text-content {
  p {
    @apply my-2 first:mt-0 last:mb-0;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    @apply mt-6 mb-3 font-semibold text-foreground leading-tight first:mt-0;
  }

  h1 {
    @apply text-3xl;
  }
  h2 {
    @apply text-2xl;
  }
  h3 {
    @apply text-xl;
  }
  h4 {
    @apply text-lg;
  }

  ul,
  ol {
    @apply my-3 pl-6;

    li {
      @apply my-1;
    }
  }

  strong {
    @apply font-semibold text-foreground;
  }

  em {
    @apply italic;
  }

  a {
    @apply text-primary underline underline-offset-2 transition-colors hover:text-primary/80;
  }

  code {
